text:
&.config-selection {
  gap: 0;
  &.single {
    gap: var(--hub-space-medium);
  }

  &.is-showing-shared-config .shared-config-item,
  &:not(.is-showing-shared-config) .config-common {
    display: none;
  }
}

& .selection-grid {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(0, 1fr);
  grid-template-rows: auto;
  gap: var(--hub-space-medium);

  & .config-column {
    display: flex;
    flex-direction: column;
    gap: var(--hub-space-medium);

    .credentials-confirmation & {
      gap: var(--hub-space-large);
      padding-block: 15px;
    }
  }

  .credentials-confirmation & {
    padding-inline: 15px;
  }

  .single & {
    display: block;
  }
}
